import{_ as a,o as r,c as s,a3 as e}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"存档页：改威望与回合","description":"","frontmatter":{},"headers":[],"relativePath":"use/save-page.md","filePath":"use/save-page.md","lastUpdated":null}'),o={name:"use/save-page.md"};function l(n,t,i,d,h,c){return r(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="存档页-改威望与回合" tabindex="-1">存档页：改威望与回合 <a class="header-anchor" href="#存档页-改威望与回合" aria-label="Permalink to &quot;存档页：改威望与回合&quot;">​</a></h1><p><strong>直接修改当前正在进行的战役。</strong> 这是最需要谨慎的一页。</p><h2 id="前提-必须先进战役" tabindex="-1">前提：必须先进战役 <a class="header-anchor" href="#前提-必须先进战役" aria-label="Permalink to &quot;前提：必须先进战役&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">这一页在「战役大地图」里才能用</p><p>如果你在主菜单、或者没开任何战役，这页会提示「<strong>请先进战役大地图</strong>」。</p><p>这是正常的 —— 没有战役就没有可改的存档。</p></div><h2 id="能改什么" tabindex="-1">能改什么 <a class="header-anchor" href="#能改什么" aria-label="Permalink to &quot;能改什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>操作</th></tr></thead><tbody><tr><td><strong>威望</strong></td><td>加减 1 千 / 1 万，或一键设 10 万 / 50 万 / 100 万 / 满</td></tr><tr><td><strong>回合</strong></td><td>加减 1 / 加减 10</td></tr><tr><td><strong>舰船数</strong></td><td><strong>只读</strong>，看当前有几艘（不能改）</td></tr></tbody></table><h2 id="威望" tabindex="-1">威望 <a class="header-anchor" href="#威望" aria-label="Permalink to &quot;威望&quot;">​</a></h2><h3 id="快捷加减" tabindex="-1">快捷加减 <a class="header-anchor" href="#快捷加减" aria-label="Permalink to &quot;快捷加减&quot;">​</a></h3><p>「+1 千」「-1 千」「+1 万」「-1 万」按钮，点一下改一点。</p><h3 id="一键设值" tabindex="-1">一键设值 <a class="header-anchor" href="#一键设值" aria-label="Permalink to &quot;一键设值&quot;">​</a></h3><p>直接把威望设成某个值：</p><table tabindex="0"><thead><tr><th>按钮</th><th>设为</th></tr></thead><tbody><tr><td>10 万</td><td>100,000</td></tr><tr><td>50 万</td><td>500,000</td></tr><tr><td>100 万</td><td>1,000,000</td></tr><tr><td>满</td><td>上限值</td></tr></tbody></table><h3 id="硬边界" tabindex="-1">硬边界 <a class="header-anchor" href="#硬边界" aria-label="Permalink to &quot;硬边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>范围</th></tr></thead><tbody><tr><td>威望</td><td><strong>0 – 9,999,999</strong></td></tr><tr><td>回合</td><td><strong>0 – 9999</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">超范围会被截断</p><p>往上下限外面加会停在边界值，不会溢出成负数或怪数。</p></div><h2 id="回合" tabindex="-1">回合 <a class="header-anchor" href="#回合" aria-label="Permalink to &quot;回合&quot;">​</a></h2><p>「+1」「-1」「+10」「-10」按钮，调整战役的回合数。</p><div class="tip custom-block"><p class="custom-block-title">什么时候需要改回合</p><ul><li><strong>往前推</strong> —— 想跳过等待，直接到某个时间点</li><li><strong>往回退</strong> —— 想「重来」某几回合（但要小心，不是所有状态都会跟着回退）</li></ul><p>改回合主要是改变<strong>战役的时间推进</strong>，不是「读档」。</p></div><h2 id="关键-必须点「保存到存档」" tabindex="-1">关键：必须点「保存到存档」 <a class="header-anchor" href="#关键-必须点「保存到存档」" aria-label="Permalink to &quot;关键：必须点「保存到存档」&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">改完一定要点保存</p><p><strong>拖动或点击只改了内存里的值。</strong> 要点「<strong>保存到存档（写盘）</strong>」才真的写进存档文件。</p><p>不保存的话，退出游戏就白改了。</p></div><p>保存也是<strong>两段确认</strong>的操作。</p><h2 id="安全设计-为什么不会弄坏存档" tabindex="-1">安全设计：为什么不会弄坏存档 <a class="header-anchor" href="#安全设计-为什么不会弄坏存档" aria-label="Permalink to &quot;安全设计：为什么不会弄坏存档&quot;">​</a></h2><p>这是框架里最值得说明的安全设计之一。</p><div class="tip custom-block"><p class="custom-block-title">它不直接改存档文件</p><p>游戏的存档是<strong>二进制格式</strong>（<code>rncampaignInfo.dat</code>），直接改字节非常容易弄坏。</p><p>框架的做法是：</p><ol><li>找到<strong>运行时</strong>的战役对象</li><li>改它的<strong>公开字段</strong>（威望、回合）</li><li>调用<strong>游戏自己的保存方法</strong>写盘</li></ol><p>也就是说：<strong>用的是游戏官方的序列化流程</strong>，写出来的还是游戏能正常读的格式。</p></div><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;你改威望&lt;br/&gt;（改内存值）&quot;] --&gt; B[&quot;点保存&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;框架调用&lt;br/&gt;游戏自带 Save()&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;游戏用自己的格式&lt;br/&gt;写入存档文件&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;存档格式&lt;br/&gt;100% 正常&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">对比一下「直接改文件」的风险</p><table tabindex="0"><thead><tr><th>做法</th><th>风险</th></tr></thead><tbody><tr><td>直接改二进制字节</td><td>极容易弄坏，游戏读不出 = 存档报废</td></tr><tr><td><strong>走游戏官方接口</strong>（框架的做法）</td><td>格式永远是游戏自己的，读得出</td></tr></tbody></table><p>所以框架能保证：<strong>改过的存档仍然是游戏能正常读取的格式。</strong></p></div><h2 id="但有件事框架不负责" tabindex="-1">但有件事框架不负责 <a class="header-anchor" href="#但有件事框架不负责" aria-label="Permalink to &quot;但有件事框架不负责&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">框架只负责改，不回滚</p><p><strong>改过的值是永久的。</strong> 框架不会记录「你改之前是多少」。</p><p>所以：</p><ul><li>改之前，<strong>看一眼页面上显示的当前值</strong>，心里有个数</li><li>或者干脆先备份存档文件</li></ul></div><h2 id="界面上显示的值" tabindex="-1">界面上显示的值 <a class="header-anchor" href="#界面上显示的值" aria-label="Permalink to &quot;界面上显示的值&quot;">​</a></h2><p>这一页会<strong>实时显示</strong>当前战役的：</p><ul><li>当前威望</li><li>当前回合</li><li>舰船数量</li></ul><p>这些是<strong>打开页面时读到的真实值</strong>。所以改之前你能看到原值。</p><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><h3 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>做法</th></tr></thead><tbody><tr><td>想快点体验后期内容</td><td>一键设 100 万</td></tr><tr><td>缺一点点钱买船</td><td>加 1 万</td></tr><tr><td>想跳过漫长的等待</td><td>回合 +10</td></tr><tr><td>想测试舰队配置</td><td>威望拉满，买船实验</td></tr></tbody></table><h3 id="什么时候别用" tabindex="-1">什么时候别用 <a class="header-anchor" href="#什么时候别用" aria-label="Permalink to &quot;什么时候别用&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">会破坏游戏乐趣</p><p>用「存档页」直接给钱，<strong>跳过了整个资源管理玩法</strong>。</p><p>如果你是第一次玩，建议先正常玩一段（至少到中期），再决定要不要用。</p><p>「<a href="/AtlanticFleetSite/docs/features/economy">经济与威望</a>」里的 <code>renownGainMul</code>（收入倍率）是更温和的做法 —— 它让你赚得快，但还是要赚。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="提示「请先进战役大地图」" tabindex="-1">提示「请先进战役大地图」 <a class="header-anchor" href="#提示「请先进战役大地图」" aria-label="Permalink to &quot;提示「请先进战役大地图」&quot;">​</a></h3><p>你还没进任何战役。先开始或继续一个战役，再打开这一页。</p><h3 id="改了但重开游戏后没变" tabindex="-1">改了但重开游戏后没变 <a class="header-anchor" href="#改了但重开游戏后没变" aria-label="Permalink to &quot;改了但重开游戏后没变&quot;">​</a></h3><p><strong>点「保存到存档」了吗？</strong> 不点保存，退出就白改了。</p><h3 id="改完游戏读档异常" tabindex="-1">改完游戏读档异常 <a class="header-anchor" href="#改完游戏读档异常" aria-label="Permalink to &quot;改完游戏读档异常&quot;">​</a></h3><p>理论上不会（因为走的是官方接口），但如果真出现：</p><ol><li>用 <a href="/AtlanticFleetSite/docs/deploy/uninstall">部署文档</a> 里的方法恢复存档备份</li><li>或者装回纯汉化版</li></ol><div class="tip custom-block"><p class="custom-block-title">建议先备份</p><p>虽然框架走的是安全路径，但<strong>重大改动前备份存档</strong>是个好习惯。</p><p>存档位置：<code>Android/data/&lt;游戏包名&gt;/files/rncampaignInfo.dat</code></p></div><h3 id="舰船数为什么不能改" tabindex="-1">舰船数为什么不能改 <a class="header-anchor" href="#舰船数为什么不能改" aria-label="Permalink to &quot;舰船数为什么不能改&quot;">​</a></h3><p>因为舰船是<strong>一个复杂的对象集合</strong>（每艘船有自己的状态、损伤、位置），不像威望那样是一个数字。</p><p>直接改这个容易造成数据结构不一致，所以框架只<strong>读</strong>不<strong>写</strong>。</p><p>想改舰队组成，用游戏内的正常流程。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>温和的经济调节 → <a href="/AtlanticFleetSite/docs/features/economy">经济与威望</a></li><li>新战役起始资源 → <a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a></li><li>存档安全说明 → <a href="/AtlanticFleetSite/docs/deploy/first-run">首次启动与目录</a></li></ul>`,52)])])}const u=a(o,[["render",l]]);export{b as __pageData,u as default};
